"use strict";

/* Method is the canonical reference behind every "How this works" link. It opens as
   eight named chapters with a table of contents, so a newcomer meets summaries rather
   than a wall of formulas, and contextual help can deep-link straight to a chapter. */
const methodOpenChapters=new Set(["method-start"]);
function rememberMethodChapter(node){if(!node||!node.id)return;if(node.open)methodOpenChapters.add(node.id);else methodOpenChapters.delete(node.id)}
function methodChapters(){
  return [
    {id:"method-start",title:"Start here",summary:"The operating loop, cash versus BTC, the operating bill and how to read your ledger.",lead:"Mining earns BTC. Running the operation costs cash. Those are two separate balances, and BTC has to be sold before it can pay for electricity. At each month boundary the recurring costs you have accrued are settled from liquid cash — that settlement is the operating bill. Most runs end because the cash ran out, not because the mining stopped.",body:`<h3>Clock, story and simulation speed</h3><p>One simulation day advances per tick. The story feed progresses through dated chapters; Story pause stops the clock at major chapters, and entering Mine pauses time while you shop for hardware, restoring your selected speed on exit. After the historical data cutoff, Sandbox continuation keeps the operation running for up to 100 further simulated years. Price, network hash rate, difficulty, transaction fees and block height all continue on a procedural model — deterministic and bounded, not a forecast — while halvings keep landing on schedule exactly as they always have; hardware and story events don't gain any new entries, since nothing real exists to add. The continuation itself ends at that 100-year mark.</p><h3 id="method-reference">Quick reference</h3><h4 id="method-ledger">Reading the ledger</h4><p>Mining income is written once per simulated day, not once per block: a solo entry reads <code>Block reward (today)</code> — or <code>Block reward ×N (today)</code> when more than one block landed — so the figure is that day's total subsidy plus fees, never a single block's reward. Pool mining logs the same daily total as a pool payout.</p><h4>Asset map and live header</h4><p>The header is the live asset snapshot: <strong>Liquid fiat</strong> is spendable cash; <strong>Illiquid fiat</strong> is ETF plus Strategy equity value that must be sold before it can pay a bill; <strong>Self-held BTC</strong> is hot plus cold bitcoin under your keys; <strong>Custodial BTC</strong> is exchange or frozen-claim exposure; and <strong>Lightning locked</strong> is hot BTC committed to routing channels. Every satoshi you still hold at the end counts toward the final score the same way, whether it sits in self-held keys, on an exchange, in a frozen claim or locked in a Lightning channel.</p><table><tr><th>Asset</th><th>What it means</th><th>Can it pay a bill? / Operator Score</th></tr><tr><td>Liquid fiat</td><td>Cash available for bills, miners and market orders</td><td>Spendable; supports reserves</td></tr><tr><td>Illiquid fiat</td><td>ETF and Strategy equity market value</td><td>Sell first to pay a bill</td></tr><tr><td>Self-held BTC</td><td>Hot and cold wallet bitcoin under your keys</td><td>Spendable now; included in final score</td></tr><tr><td>Custodial BTC</td><td>Exchange and frozen-claim balances</td><td>Venue-dependent; included in final score</td></tr><tr><td>Lightning locked BTC</td><td>Hot BTC committed to routing channels</td><td>Withdraw before spending; included in final score</td></tr></table><h4>Strategy equities</h4><p>Strategy securities are optional, fiat-priced capital-structure exposure to Strategy's Bitcoin-treasury business — not Bitcoin, not self-custody, not liquid fiat. Their game price starts from a model price and moves with Bitcoin from the security's unlock date using its BTC sensitivity: a gameplay proxy, not a recreation of historical security prices.</p><table><tr><th>Ticker</th><th>In-game exposure</th><th>Modelled fiat income</th></tr><tr><td>MSTR</td><td>Common equity; 1.65× BTC sensitivity</td><td>None</td></tr><tr><td>STRK</td><td>Strike preferred; 0.35× BTC sensitivity</td><td>8% annual accrual</td></tr><tr><td>STRF</td><td>Strife preferred; 0.20× BTC sensitivity</td><td>10% annual accrual</td></tr><tr><td>STRD</td><td>Stride preferred; 0.25× BTC sensitivity</td><td>10% annual accrual</td></tr><tr><td>STRC</td><td>Stretch preferred; 0.08× BTC sensitivity</td><td>9% annual accrual</td></tr></table><p>Buy and sell Strategy shares in Market using liquid fiat. They appear in Finance as illiquid fiat and count toward net worth, but can't pay a bill until sold; every preferred position uses a simplified daily fiat accrual at its displayed annual rate, not a real-world dividend guarantee.</p><h4>Starting difficulty and Starting Liquidity</h4><p>Difficulty moves the campaign start date, while Starting Liquidity sets the opening liquid cash from a $1,500 default up to the current $1,500,000 maximum. Easy begins at the Genesis Block itself, 03 January 2009; Standard opens a month later, on 03 February 2009; Hard starts 29 January 2013, as the first ASICs ship and CPU, GPU and FPGA hardware is already obsolete for competitive mining; and Impossible starts 01 January 2025, after the fourth halving with under 20 months of historical record left before the campaign end date. It changes nothing else: not historical prices, network data, hardware dates, incident rules or scoring weights, and the selected mode is stored permanently in the activity ledger.</p><h4>Transaction sizing and procurement</h4><p>Percentage-sized actions use the named source balance at review time: liquid cash for buys, the selected BTC wallet for sells and transfers, or the held security position for security sales. Miner orders are whole units, capped by cash or hot BTC, facility power, floor space and outstanding reserved capacity; opening a confirmation pauses the simulation, so execution uses the same figures shown in the review. Miner purchases are prepaid but can slip on modelled lead times; delivered equipment stays staged until commissioned. At each month boundary the operation settles electricity, rent, internet, staff, insurance, node services and finance interest together — a shortfall pauses time for an explicit sale, liquidation, bridge-finance or receivership decision.</p><h4>Operator Score</h4><p>Up to 740 points come from era performance: bills paid, realised mining profitability, uptime and keeping a competitive fleet, and a further 60 from operator mastery — your peak level, capped at level 50. Milestones and total BTC holdings — self-held, custodial and Lightning-locked combined — contribute up to 120 points. Cash reserves and resilience against bridge loans or receivership contribute the final 80. Starting with more cash makes survival easier but does not directly change these weights.</p><h4>Where the historical data comes from</h4><p>${(()=>{const meta=(window.HISTORICAL_DATA||{}).meta;if(!meta)return "The recorded series are bundled with the build.";const counts=(window.HISTORICAL_DATA?[["PRICE","BTC/USD price"],["DIFFICULTY","difficulty"],["HASH","network hash rate"],["FEES","transaction fees"],["TX","transaction count"],["HEIGHT","block height"],["CAP","market capitalisation"]].filter(([key])=>Array.isArray(window.HISTORICAL_DATA[key])).map(([key,label])=>`${fmtNum(window.HISTORICAL_DATA[key].length)} ${label}`).join(", "):"");return `Every recorded series in this game is pulled from <strong>${meta.source}</strong> and regenerated by a script in the repository rather than typed in by hand — the bundled file carries ${counts}, current through ${dateFmt(at(meta.through),true)}. Nothing about the market, the network or the chain is invented.`})()}</p><table><tr><th>Series</th><th>How it was derived</th></tr>${Object.entries(((window.HISTORICAL_DATA||{}).meta||{transforms:{}}).transforms||{}).map(([key,how])=>`<tr><td>${key}</td><td>${how}</td></tr>`).join("")}</table><p class="modal-note">Where a series is sampled weekly rather than daily, values between samples are interpolated, and the tab labels that as ${sourceTag("derived")} rather than ${sourceTag("recorded")}. Pool market shares are separate: early history is smoothed, and 2024 onward uses weekly block-attribution observations from mempool.space. Hardware prices, incident rates, uptime, repair behaviour and every outcome in the game are ${sourceTag("modelled")} — they are not in the dataset and are not claimed to be.</p><h4>What is historical vs modelled</h4><table><tr><th>Class</th><th>Meaning</th><th>Examples</th></tr><tr><td>${sourceTag("recorded")}</td><td>Historical anchor</td><td>Dates, price points, halvings, known events</td></tr><tr><td>${sourceTag("derived")}</td><td>Calculated from anchors and your state</td><td>Network share, expected yield, bills, net worth</td></tr><tr><td>${sourceTag("modelled")}</td><td>Gameplay simplification</td><td>Hardware prices and resale, incidents, outages, venue freezes, Lightning fees, part-fault attribution, repair complications, overdrive risk multipliers, venue bid/ask spreads, order-book depth and trade impact</td></tr></table><p class="modal-note">The purpose is to expose the economic relationships that come with running a Bitcoin operation through changing eras — not to predict Bitcoin prices or promise investment returns.</p></article>`},
    {id:"method-rewards",title:"Mining and rewards",summary:"Hash rate, network difficulty, subsidy, transaction fees, solo variance and pool schemes.",lead:"Your machines compete for blocks against the entire network. How often you win depends on your share of the total work being done; what a win pays depends on the block subsidy, the fees in the block, and whether you mine solo or through a pool. This chapter makes both of those precise.",body:`<h3 id="method-mining">Mining probability and payout</h3><p>How often you win comes down to one number: your share of all the work being done. Add hash rate and your share rises, but so does the total you are dividing into, so a bigger fleet never earns quite proportionally more. Downtime costs you directly — a machine that is not running is not entered in the draw at all.</p><details class="method-detail"><summary>Exact calculation</summary><p>Your effective share is <code>active fleet hash ÷ (effective competitive hash + active fleet hash)</code>. Effective competitive hash is not simply the recorded historical network hash: it is the larger of that historical baseline and a modelled floor for unseen miners, plus a scaling response to the size of your own fleet — buying hardware does not just divide a fixed pie. Expected blocks per day is <code>144 × share × uptime</code>, where uptime is regional grid reliability, capped at 100%, plus a small Monitoring bonus. Expected BTC per day multiplies those blocks by the current subsidy plus the modelled transaction-fee component.</p></details><p><strong>The early years are deliberately damped, and by a large factor.</strong> Run the honest formula on February 2009 and one laptop at 5 MH/s against difficulty 1 finds about 100 blocks a day — roughly 5,000 BTC — because that is genuinely what the arithmetic said when almost nobody was hashing. A campaign that hands you that in week one is over before it starts, so the modelled competition is scaled up early and tapered away. From the ASIC era onward the simulation is running the real arithmetic; before it, it is not, and that is a game-balance decision rather than a historical claim. At your current fleet and date the factor is <strong>${(yieldDampingAt(state.time,fleet().hash)*100).toFixed(0)}%</strong> of the unmodified rate.</p><details class="method-detail"><summary>The damping factor, year by year</summary><p>Modelled competition is scaled by about 60× in 2009, 40× in 2010, 12× in 2011, 4× in 2012, 1.5× in 2013 and 1× from 2014 onward. Measured against the unmodified formula, the effect on your yield is roughly <strong>0.02× in early 2009, 0.04× in mid-2010, 0.11× in 2011, 0.69× in 2013, 0.92× in 2017 and 0.99× from 2024</strong>.</p></details><table><tr><th>Mechanic</th><th>Solo</th><th>Pool</th></tr><tr><td>Underlying odds</td><td>Your share of block-finding probability</td><td>Same expected share</td></tr><tr><td>Variance</td><td>High: whole blocks arrive randomly</td><td>Low: rewards are smoothed</td></tr><tr><td>Fee</td><td>None</td><td>${(poolFee()*100).toFixed(2)}% currently · ${POOL_SCHEMES[poolScheme()].name}</td></tr><tr><td>Reward timing</td><td>Can be very long between wins</td><td>Small, regular simulated payouts</td></tr></table><p><strong>Does your own hash rate move difficulty?</strong> Yes, and the share formula is where it happens. Your odds are <code>your hash ÷ (competition + your hash)</code>, so the hash you add sits in your own denominator exactly as it would sit in the network total that difficulty retargets against. The practical consequence matches the real thing: below about 1% of the network, doubling your fleet almost exactly doubles your blocks, because you barely move the total. Past that it visibly bites — at roughly 2.5% of network hash, per-machine yield is about 12% lower than the same machine would earn in a small fleet. What the game does <em>not</em> do is rewrite recorded history: the displayed difficulty is the real reconstructed series for that date, not a counterfactual in which your fleet also existed.</p><p><strong>Your best share.</strong> Every hash your fleet completes is a lottery ticket, and the difficulty of the best one is the number miners actually watch. Your record climbs in rare jumps rather than smoothly, and it is reconciled with what the day actually produced rather than tracked separately.</p><details class="method-detail"><summary>Exact calculation</summary><p>The chance of a share reaching difficulty <em>d</em> is <code>1/d</code>, so the day's best share is heavy-tailed. Because a share at or above the network difficulty <em>is</em> a valid block, mining solo your best share crosses network difficulty on exactly the days you find a block and never on the days you do not. Pool mining, a share above network difficulty is you finding the block on the pool's behalf, which the Ledger names.</p></details><p>Solo mining draws a seeded Poisson process, so a small miner can go a long time between blocks and then find several in a row. Pool mining smooths the same expected economics, less the selected pool's fee; each historical pool carries its own approximate market share and base fee, and the Operations skill tree can trim that fee by up to 0.4 percentage points.</p><p><strong>The payout scheme matters as much as the headline fee</strong>. <strong>FPPS</strong> pays a flat rate per share covering the subsidy <em>and</em> an average of transaction fees, whether or not the pool finds a block — the pool absorbs the variance and prices it in. <strong>PPS</strong> pays the subsidy only and keeps the transaction fees; that was near-irrelevant in 2011 when fees were a rounding error, and expensive later. <strong>PPS+</strong> pays subsidy as pay-per-share and passes fees through on what the pool actually collects. <strong>PPLNS</strong> and OCEAN's <strong>TIDES</strong> pay you only out of blocks the pool really finds, weighted by your recent shares: identical expected return, real variance, and the cheapest fees. <strong>Proportional</strong> and <strong>score</strong> sit further along the same axis, with proportional the most exposed to a long unlucky round.</p><details class="method-detail"><summary>When each scheme was invented</summary><p>Schemes arrived at particular moments rather than always existing, so each pool here carries a dated timeline rather than one fixed method. Proportional came first and paid out whatever the round produced, which made it hoppable; Slush answered that in November 2010 with a time-weighted <strong>score</strong>, and ran it until moving to FPPS on 12 December 2023. <strong>PPLNS</strong> appeared around 2011 and <strong>PPS</strong> shortly after. <strong>FPPS</strong> only became possible once transaction fees were worth passing on, arriving around 2014-15 and becoming the industry default. <strong>PPS+</strong> was ViaBTC's invention in August 2016, and OCEAN's <strong>TIDES</strong> arrived with the pool in November 2023. A pool in this game is never shown running a scheme before it existed, and a regression check enforces it.</p></details><p>The trade-off is live rather than cosmetic. In mid-2023, with transaction fees running about 7% of the block reward, a 0%-fee FPPS pool and a 0%-fee TIDES pool return the same expected BTC per day but the TIDES payout swings roughly fourteen times as widely day to day. Over the same window a 3% PPS pool lands about <strong>9.8%</strong> below the best available option, not 3% — the missing 7 points are the transaction fees it never passes on. A headline fee is not a like-for-like comparison, and the game does not pretend otherwise. A pool that historically shut down stops being selectable once its closure date arrives; if it was your active method when that happens, the fleet fails over to solo mining automatically and the live floor's connection panel reflects the switch.</p>`},
    {id:"method-fleet",title:"Fleet and facilities",summary:"Capacity, power, cooling, condition, faults, connectivity, procurement and commissioning.",lead:"A machine only earns while the site can power it, cool it and hold it, and while it is in working order. This chapter covers what you can buy, what it costs to run, how it wears out and what it takes to bring it back.",body:`<h3 id="method-hardware">Hardware: purchase, fit and resale</h3><p>Each machine contributes hash rate, watts and floor space; a purchase is only accepted if the resulting fleet still fits both electrical capacity and floor space. A purchase places an order that arrives after a modelled lead time — subject to vendor-specific delay and partial-delivery risk — reserving its capacity immediately so you can't oversell the site. Delivered units then sit staged until commissioned: commissioning racks, configures and tests the batch over several more simulation days, twice as fast with a field technician on staff, and only after that does the batch start hashing, drawing power and accumulating wear. Firmware tuning adds 4% hash, undervolting removes 5% power draw, ASIC tuning adds a further 5% hash on ASIC and hydro ASIC machines, and the Procurement skill plus a Procurement lead together cut purchase cost by roughly 11%. Hydro ASICs also need the liquid-cooling skill and a warehouse-tier facility or larger; otherwise they stay installed but offline.</p><p id="method-secondhand"><strong>Hardware prices do not hold, and that is the point.</strong> A machine sells near its listed price for about six months while it is the current thing, and then falls away fast — halving roughly every fifteen months, down to a 3% floor. It also moves ±30% with the trailing year\'s BTC momentum, because hardware prices collapsed hardest in bear markets rather than merely with age. An S9 listed near $2,100 in 2016 and traded for a couple of hundred by 2019; the game prices it that way rather than charging list forever.</p><p>This is what makes the catalog a decision rather than a list. The newest machine is still the best buy wherever electricity is expensive — that is true to life and does not change. But where power is cheap, a four or five year old machine at a small fraction of its old price can pay back faster than anything new, which is exactly why worn ASICs migrated to the cheapest grids in the world and kept running there for years. A machine bought long after release is a used machine and arrives with the wear that implies, down to 70% condition, which keeps it clear of the 65% threshold that takes a hardware type offline but leaves it closer to trouble than a new one. Buying used drags the whole type\'s condition down proportionally, because condition is tracked per type rather than per unit.</p><p>A liquidation glut — the Compute North and Core Scientific bankruptcies both trigger one — softens secondary prices for a season. That is bad if you are selling and good if you are buying, and it now applies to both.</p><p>Retiring a machine and selling it returns its current market value less a 35% spread. Resale used to depreciate on a curve of its own, independent of what buying cost; once purchase prices depreciated too the two crossed, and a decade-old machine could be bought and instantly resold for more than it cost. Pricing the sale off the same market value makes that impossible rather than merely unlikely. Selected breakthrough generations also carry a temporary launch-edge multiplier on hash rate — full for their first year, fading through the second, then gone. That's a modelled profitability window, not extra physical hash rate.</p><p>Every hardware generation announces itself when it reaches the catalog: ASIC-class launches pause the simulation with a full release brief, while earlier CPU, GPU and FPGA-era machines — not dramatic enough for that — get a lighter notification instead, so a new option never appears silently.</p><h3 id="method-maintenance">Fleet servicing: condition, faults and repair</h3><p>Every installed hardware type carries a <strong>condition</strong> score that falls slowly while active — faster the older the machine, and faster still the hotter the room: above 28 °C wear accelerates, and above 30 °C so does the chance of an outright fault. Field technicians on payroll cut that wear rate by up to 65%. If a type's condition drops below 65%, the whole type goes offline until a <strong>full refurbishment</strong> restores it — that's scheduled maintenance, not a random event, and it's still available above 65% as a smaller top-up.</p><p>Independently, active units can suffer a random fault at any condition. Each fault is attributed to one specific failed part — hashboard, power PCB, cooling fan, or on hydro ASICs a coolant pump or manifold — weighted by what that hardware era actually needs: an ASIC fault is disproportionately a hashboard or power-PCB problem, while a GPU or FPGA fault is more likely a fan or power PCB. Only the units carrying that specific fault stop hashing; the rest of the type keeps running.</p><p>Parts are not interchangeable across eras, and their prices are not flat. Cooling splits three ways by what the machine actually uses — a small internal laptop fan for CPU-era kit, a 120mm case fan for GPU rigs and FPGA boards, and a compact high-static-pressure blower for dense ASIC racks — and stays roughly flat in cost, because a fan is a fan. Hashboards are where maintenance economics bite: an early hashboard for first-generation ASICs is the cheapest board in the game, a mid-generation board costs several times that, and a current-generation high-density board (shared with hydro miners) costs several times again, selected automatically from each machine's era and release date. Keeping an old fleet alive is genuinely cheap; keeping a modern one alive is not.</p><p>Completing a targeted swap clears that part's outstanding faults outright rather than decrementing a counter, and restores condition to a level that stays clear of the 65% offline threshold once the same day's wear is applied — so a part you just replaced does not immediately present as faulted again.</p><p>Two repair actions follow, both on the Mine tab next to the live floor: a <strong>targeted part swap</strong> replaces just the faulted units of one part, consuming only that spare-part type and finishing faster and cheaper than a full job; a <strong>full refurbishment</strong> uses the complete parts bundle for that hardware era and restores condition wholesale. Both need spare parts in stock — order ahead, since normal lead time is 14 days (8 with Supply-chain contacts), or 42 days at 2.25× cost during the modelled COVID supply shock — and both need a technician crew: up to three field technicians can work one hardware type at once. A faulted or repairing unit shows its specific part or job status right on the live floor, including which hardware type each assigned technician sprite is currently working on.</p><p>A scheduled repair is not instant: it moves through six labour stages — power down, disconnect, work, reconnect, fit &amp; rack, stability check — each with its own chance of a complication. A complication adds delay and, if cash allows, a small callback fee; on the Work stage specifically it has a further chance of uncovering a second fault on a different part, which becomes its own future repair rather than extending the current job. The <strong>Field service technique</strong> skill halves the complication chance at every stage, and working alone (no technician on payroll) complicates more often than a trained in-house crew does. With nobody hired the labour is free, because it is your own — but only one self-serviced job can run at a time across the entire fleet, so a second fault has to wait its turn or you hire a technician. Left alone, an active fault also carries a small daily chance of spreading to a second part, so ignoring one is a real, compounding cost rather than a free pass. Until you have a field technician on payroll, <strong>you are the one holding the spanner</strong>, and your own labour is free — a self-serviced job charges you for parts and nothing else. Every repair you start yourself stops at its Work stage and waits for you — a full refurbishment or a targeted part swap alike — with a puzzle that varies job to job: a torque sequence, a cable-matching board or a calibration dial, so the exact task changes each time. A targeted swap additionally needs the old part pulled before the puzzle starts; a full refurbishment skips straight to it. Nothing else about the stage timeline advances until it's solved, and because it is only ever you, one self-serviced job can run at a time across the whole fleet. This is not limited to the years before you hire anyone: whenever every technician on payroll is already committed to another repair, the next job falls to you rather than being refused, so a parts-in-stock fault is never blocked purely by crew availability. Only when your own bench is occupied too does a further job have to wait. Getting it wrong has teeth: a mis-torqued bolt, a mismatched connector pair or an over-torque past spec can <strong>damage the machine you are working on</strong>, costing several points of condition and sometimes breaking a second part outright, which becomes its own new fault. That risk falls sharply with practice on that specific hardware type — the Mine floor's bench panel shows the current damage risk and completed-repair count for every type you own, starting near 40% for a machine you have never opened and decaying to a 2% floor.</p><p>Four Operations skills exist purely to keep you self-sufficient for longer. <strong>Bench repair skills</strong> cut the damage risk to 40% of its value. <strong>Parts sourcing</strong> takes 20% off every spare part. <strong>Supply-chain contacts</strong> bring orders in 40% sooner, supply shock included. <strong>Practised hands</strong> gives a familiar repair a growing chance to complete itself with no puzzle at all — 20% on a type you have serviced once, rising to a capped 85% once you have done eight. None of them require a facility tier, so a solo operator can invest in their own competence from the opening years. Hiring changes the nature of the work rather than only its speed: a technician crew completes its own jobs end to end and never hands the Work stage back to you, and up to three technicians can share one hardware type to finish it faster, and an <strong>auto-repair</strong> toggle on the Mine floor then lets that crew clear the whole backlog of eligible jobs from stock and payroll alone.</p><h3 id="method-firmware">Firmware security</h3><p>Mining ASICs need a signed firmware review, first from 26 April 2017 and roughly every 18 simulated months after that. Skipping one leaves unreviewed firmware running on the machines that earn your income, and the risk is not that they stop — it is that part of what they earn quietly goes somewhere else.</p><details class="method-detail"><summary>Exact calculation</summary><p>ASIC and hydro ASIC fleets are affected. An overdue review creates a monthly hijack risk; if it triggers, 35% of mining reward is diverted to an attacker until the fleet is reflashed from Facilities. Reflashing costs <code>max($75, $18 × ASIC count)</code> and clears the compromise immediately.</p></details><h3 id="method-energy">Energy, cooling and the operating bill</h3><p>Electricity is the cost attached to your hash rate, and you pay it for every hour a machine runs, not for every reward it earns. What you use depends on the miners, the cooling that keeps them alive and any nodes you run. What you pay per unit depends on the region, your power contract and how densely you have packed the site — past about 55% of capacity, the same electricity starts costing more.</p><p>A room settles where the heat going in equals the heat getting out, and a room sheds heat in proportion to how much hotter it is than the air outside. Every site therefore has a rate rather than a limit: how many kilowatts it loses per degree of difference. Cooling ratings are quoted as what the equipment can reject at a ten-degree difference, so a rating divided by ten is that rate. One 1.3 kW machine in a spare room that sheds a kilowatt at ten degrees settles thirteen degrees above the outside air — comfortable in January, a problem in July, and back under control for the price of a box fan.</p><p>Enclosed sites have a floor, because a spare room sits inside a heated house and an industrial unit holds some background warmth. A container yard has no floor and tracks the weather. Regional climates are annual means with a seasonal swing that peaks about a month after the solstice, so the same fleet in the same room is a different problem in summer.</p><p>Cooling equipment is ordered and installed rather than switched on: it is paid for up front, but rejects no heat until the installers finish, which takes three days for a box fan and four months for a cooling tower. Its peak draw is reserved against the site's supply from the moment you order, so a site that cannot power the plant cannot book it. Once running it draws its own share of the site's power and raises the rate at which the room sheds heat, which is what pulls the temperature down. It never faults itself; only the miners it protects do. Rent, staff, insurance and node power are separate fixed overhead. Bills accrue daily and settle at the month boundary, and a shortfall creates grid arrears that disconnect the site until it is paid.</p><h4 id="method-demand-response">Demand response and curtailment</h4><p>A curtailment contract is not simply a promise to use less power — it is an agreement to give capacity back to the grid when the grid is short, and to be <strong>paid</strong> for the capacity you release. That payment is the entire reason an operator signs one. It is also why some large operations earn more from power credits than from mining in a bad month: Riot's Rockdale site did exactly that during 2023, which is the operation the "A Texas miner grows grid-sized" chapter is about.</p><p>Because demand response is called when the grid is stressed, curtailment in this game tracks the same recorded energy shock that raises everyone else's tariff. In calm months it is a light standing obligation of about 5% of your load. During the 2022–23 energy crisis it rises to well over half, and the credit rises with it, because that is precisely when the capacity you are releasing is worth most.</p><p>The result is that the power contract has no single right answer. In ordinary conditions spot power is simply the cheapest way to buy electricity. When a shock arrives, a comfortably profitable site is usually better off on a fixed PPA — paying a premium to keep every machine hashing at a known price — while a site that is already marginal does better to curtail and take the credit. The worse your margin, the more attractive it is to sell your capacity back rather than mine with it.</p><details class="method-detail"><summary>Exact calculation</summary><p>Curtailed share is <code>min(60%, 5% + max(0, energy shock − 1) × 0.8)</code>. That share is removed from both your power draw and your mining output. The credit is <code>released kW × 24 × regional base tariff × energy shock × 1.4</code>, applied against the energy line of the operating bill, and it can exceed the energy charge itself. The energy shock is ${sourceTag("recorded")}; the curtailment shape and the credit multiplier are ${sourceTag("modelled")}.</p></details><details class="method-detail"><summary>Exact calculation</summary><p>Daily energy cost is <code>(active miner kW + thermostatic cooling kW + node kW) × 24 × all-in rate</code>, after any heat-reuse credit. The all-in rate is <code>regional base tariff × power-contract multiplier × historical energy shock (skipped entirely on a fixed PPA) × tech efficiency × a load-density penalty that rises once the fleet passes about 55% of facility capacity</code>. The Heat-reuse, Metering and Curtailment skills each shave a further 4% off one of those factors.</p></details><p>An optional <strong>overdrive</strong> toggle on the Mine floor pushes the whole fleet for +15% hash and +25% power draw, at the cost of 1.6× wear and 2.2× fault risk. Because it scales electrical draw too, engaging it with little headroom left can push the site over its own capacity and trip a shutdown outright — the load-density penalty and the hard capacity limit are the real consequence, not a separate risk roll.</p><h3 id="method-facilities">Facilities, regions and migration</h3><p>A facility gives you two separate limits, and you can exhaust either one while the other still has room: how much electricity the site can supply, and how much floor space it has. It also sets your rent and what the fit-out costs. A region sets what power costs, how reliable the grid is, where your internet bill starts and what it costs to leave — and historical policy events can close a region to you entirely.</p><p>Neither a facility upgrade nor a regional move is instant, and only one can be underway at a time. The fleet powers down for transport and earns nothing until it is back online, while the bills carry on. A fit-out also needs two months of operating cash in reserve on top of its construction cost, so a site you can just barely afford is not a site you can buy.</p><details class="method-detail"><summary>Exact costs, timing and incident risk</summary><p>Upgrading to a larger facility costs its fit-out price and takes several days to a few weeks — longer with a bigger fleet or a bigger tier jump, cut 20% by a Logistics lead. It carries a modelled contract, transit or seizure incident risk that rises with the size of the jump; migration insurance covers eligible incidents. Moving to a new region costs <code>relocation fee + 5% of fleet value</code>, cut 20% each and multiplicatively by the Relocation skill and a Logistics lead, and takes longer still, scaling with fleet size and how far you jump.</p></details><details class="method-detail"><summary>About the mining-floor illustration</summary><p>Each of the eight facility tiers draws its own mining floor, built from what that kind of site actually looks like — a domestic spare room on one circuit, a garage with a roller shutter and a real consumer unit, a three-phase trade unit under portal-frame trusses, a warehouse with overhead busway and extract fan banks, a substation-led campus, an outdoor container yard, a hydro plant with penstocks and a coolant manifold, and a transmission-fed megacampus. It is illustration, not simulation: your machines, their status and the room temperature above them are the parts that are real.</p></details><h3 id="method-connectivity">Internet, connectivity plans and outages</h3><p>Internet is a recurring bill that scales with the size of your site rather than being a flat fee, so the largest campuses pay hundreds of times what a home office does. A better connectivity plan costs more each month and buys a lower chance of an outage — and an outage stops mining, node and Lightning service while every fixed cost keeps accruing. Grid power and internet status show as colour-coded tiles on the Mine floor, and the Operational risk desk on Facilities carries the current state and expected restoration date.</p><details class="method-detail"><summary>Exact calculation</summary><p>The monthly bill is <code>regional jurisdiction base × connectivity-plan multiplier × facility-tier scale</code>. The starter Home office (tier 1) carries a ×1 scale, rising sharply — up to ×600 — at the largest campuses. Local fixed broadband is cheapest; dual-SIM cellular and business fibre cost more but cut outage risk and shift mining propagation slightly. Each month an operating facility faces a jurisdiction-weighted chance of a multi-day outage, which Monitoring cuts by 25%. The latency reading beside the connection tiles is cosmetic: it is modelled from the selected plan's own risk and propagation characteristics, not a separate mechanic.</p></details>`},
    {id:"method-treasury",title:"Market, treasury and finance",summary:"Prices, venues, fees, cash runway, debt and what happens on settlement day.",lead:"BTC cannot pay a bill. This chapter covers the routes between mined BTC and spendable cash, the fees and counterparty risks on each route, and what the simulation does when the cash is not there at settlement.",body:`<h3 id="method-market">Market, exchanges and venue freezes</h3><p>The game opens tradable BTC/USD on 17 July 2010, when Mt. Gox began continuous trading. That is a deliberate simplification rather than the first time bitcoin had a dollar price: New Liberty Standard published an electricity-cost-derived rate from October 2009, bitcoinmarket.com ran from March 2010, and the 10,000-BTC pizza was May 2010. What those lacked was a continuous order book deep enough to sell a mining operation's production into, which is the thing this game actually models. After that, buying spends liquid fiat and selling converts BTC at the historical price, both after a venue-specific fee; "liquid fiat" is spendable cash only — not BTC, ETF exposure or Lightning liquidity. Exchange, frozen-claim and ETF balances are custodial claims or price exposure, not self-held bitcoin. Mt. Gox and the Frontier venue can suffer historical collapse events that freeze or destroy part of a balance, and any venue carrying a balance can model a temporary withdrawal freeze that blocks sales and transfers without erasing it.</p><p>Four of those collapses had a real, documented public warning first, and the game gives you that warning — but only when you are actually exposed to it. Mt. Gox halted bitcoin withdrawals on 07 February 2014, seventeen days before it went dark; a Canadian bank froze roughly C$28M tied to QuadrigaCX's payment processor, public on 09 October 2018, about four months before that collapse; a leaked balance sheet raised questions about a major venue's sister trading firm on 02 November 2022, nine days before the bankruptcy filing; and China's top financial regulator named Bitcoin mining for the first time on 21 May 2021, about a month before Sichuan's power cuts. Each crossing writes a ledger entry and raises a persistent banner naming the exact balance or region at risk, with one click through to Market or Facilities. The banner is derived live, so it clears the moment you withdraw to zero or relocate away, and retires itself when the dated event arrives. A warning is information only — it changes nothing about the event's effect, which lands in full if you ignore it. Bitfinex's 2016 security loss and Kazakhstan's January 2022 internet shutdown deliberately carry <strong>no</strong> warning, because neither had a genuine public one; inventing advance notice for them would teach false history. Each venue quotes its own bid (what a sell here nets) and ask (what a buy here costs) around the shared historical price, built from that venue's own fee — cheaper venues quote a tighter spread.</p><p>If a monthly settlement can't be covered by cash, choosing to sell BTC does not execute a sale by itself: it opens Market with a live shortfall banner. Covering it means depositing self-held BTC onto a chosen venue and selling it there, at that venue's own quote, through the same confirmation flow as any other trade — the settlement clears itself automatically the instant cash covers the bill, from any venue, with no cap on how much you choose to sell.</p><h4 id="method-depth">Order-book depth: what a large sale actually fetches</h4><p>A quoted price is what one bitcoin trades at, not what ten thousand of them would. Every market has a finite book, and an order large enough to consume it walks the price down as it fills. The game models this, because without it an early mining fortune is a free one: in December 2010 the entire bitcoin market was capitalised at about $1.3 million, so a well-run 2009 operation's holdings were most of a percent of every bitcoin in existence — an amount that simply could not be sold at the quote, at any price, because there was nobody on the other side.</p><p>The impact you pay is proportional to the fraction of the whole market your order represents, so it depends on the market's size rather than on the date. That matters: the effect needs no era-specific tuning and retires itself. The order that was unsellable in 2010 is a rounding error by 2020, and by the cutoff a thousand-bitcoin sale costs a third of a percent — while a hundred-thousand-bitcoin sale still costs a third of its value, because that is genuinely what dumping six billion dollars into any market does.</p><p>Selling pressure carries between orders and fades over about three days, so slicing one unsellable order into a hundred small ones saves at most half the impact — roughly the advantage real execution desks get — while genuinely waiting for the book to refill works properly. Buying relieves your own selling pressure. The confirmation screen shows the impact before you commit, and the automatic settlement sale pays exactly the same impact a manual sale would, so routing a liquidation through the month-end bill is not a way around the book.</p><details class="method-detail"><summary>Exact calculation</summary><p>Impact is <code>66 × (standing same-direction pressure + order value) ÷ market capitalisation</code>, ignored below 0.1% and capped at 85%. A sale fills at <code>quote × (1 − venue fee) × (1 − impact)</code>; a buy fills at <code>quote × (1 + impact)</code>. Standing pressure decays with a three-day half-life. Market capitalisation is ${sourceTag("recorded")} — 842 weekly observations of CapMrktCurUSD from the bundled dataset, and past the cutoff it tracks the modelled price, since over 99.5% of the supply is already mined by then. The constant, and the premise that book depth scales with capitalisation, are ${sourceTag("modelled")}.</p></details><h3 id="method-finance">Finance: project loans, grid arrears and settlement rescues</h3><p>Project finance draws cash against fiat collateral or six months of recent mining revenue, charging 1.2% monthly interest — 0.9% with a Treasury manager on payroll — settled with the monthly bill. Grid arrears (an unpaid energy, rent or other bill) carry no modelled interest but force an immediate disconnection until paid.</p><p>One standing instruction decides whether that pause happens at all. Under <strong>Cover the bill</strong>, settlement sells the smallest amount of self-held BTC that clears the bill, at the market price of the day less a 0.6% fee, and only when cash falls short. Under <strong>Hold everything</strong> nothing is sold on your behalf, so a shortfall becomes a rescue decision instead. Because covering sells only the shortfall, the two behave identically in any month your cash was already enough; they differ only when you are short.</p><p>When a monthly bill exceeds available cash, time pauses for a rescue decision: sell self-held BTC on an exchange (see Market, above); liquidate the least hash-efficient miners first; take emergency bridge finance at a 15% origination premium added to project debt; miss the bill, which carries the shortfall into arrears and keeps the site running until the next bill date; or accept receivership, which seizes 10-25% of self-held BTC and 25% of installed miners (the percentage rising each time) and ends the scored campaign on its third occurrence. Only a clean cash settlement counts as a fully solvent month for the Operator Score — every rescue keeps the run alive but marks that month down.</p><p>Arrears are the one rescue with a deadline of their own. Missing a bill leaves the grid connected until the next bill date, so the operation keeps mining and the next month's costs keep accruing on top. If the arrears are still owed when that date arrives, power and internet are cut: mining and node service stop while rent, payroll, insurance and finance interest carry on. Clearing the arrears from Finance restores service the same day. Only one bill can be carried at a time — you cannot miss a second while the first is outstanding.</p>`},
    {id:"method-keys",title:"Custody and verification",summary:"Keys, hot wallets, cold storage, venues, full nodes, Lightning and counterparty risk.",lead:"Whoever holds the keys controls the bitcoin. This chapter separates BTC you control from BTC someone else is holding for you, and explains what a full node does — and does not — do for either.",body:`<h3 id="method-custody">Custody, full nodes and Lightning</h3><p>Hot and cold wallets are the only balances that count as bitcoin you actually control. From 2011, an online hot balance carries a small seeded monthly key-compromise risk that can remove 12–40% of that balance in one incident — cold storage is never touched, and Multisig cuts the odds by 58%. A node does not mine, create BTC or protect exchange balances; it independently validates the chain. Three verification profiles exist once a dedicated ($260) or hardened ($1,200, from 2016) node is bought: Pruned (12 W, $5/month, no Lightning), Archival (25 W, $20/month, enables Lightning and a lower transfer fee) and, on the hardened tier only, Mining relay (120 W, $180/month, faster propagation and routing income). A $2,400 geographic backup node (40 W, $90/month, from 2018) can carry verification through a primary-site outage but can't replace the synchronized primary for local block templates or Lightning. Falling below the modelled chain-size storage requirement takes archival service offline; pruning is the fallback, at the cost of Lightning and the cheaper transfer fee.</p><p>Lightning becomes available from 2018 with an online archival or relay node: it locks hot-wallet BTC as routing liquidity rather than spending it, earning a small daily fee proportional to locked BTC and network activity — Monitoring adds 8% to that fee — paid into the hot wallet, while the principal stays locked until withdrawn.</p><p>Every campaign opens with a one-time ceremony: roll dice for entropy, drawn from the browser's real cryptographic random number generator rather than the deterministic seed that drives the rest of the simulation, and the game derives an illustrative private key from the result — a simplification, since a real wallet performs further elliptic-curve math, checksums and address encoding this game doesn't implement. The campaign then starts on whichever wallet client era-fits its start date — the rough original client from 2009, Bitcoin-Qt from 2011, the real Bitcoin Core rebrand from March 2014, and a modern Taproot-ready release from November 2021 — with each later upgrade, once its date arrives, available from the Custody tab for a skill point.</p>`},
    {id:"method-advance",title:"Progression and scoring",summary:"Operator XP, knowledge, skills, milestones, eras and the Operator Score.",lead:"Operating well earns experience, knowledge and skill points, and those unlock lasting capabilities rather than instant multipliers. This chapter covers how each accumulates and how the final Operator Score is built from them.",body:`<h3 id="method-xp">Operator XP, levels and the best share</h3><p>A permanent experience bar in the header tracks how much operating you have actually done. XP comes from four places, all of them real mining telemetry or real work: <strong>shares submitted</strong> each day, <strong>new best-share difficulty records</strong>, <strong>machines commissioned</strong>, and <strong>repairs completed</strong> — with a 50% bonus on a repair you carried out yourself rather than handing to a crew.</p><p>Share XP is deliberately <em>logarithmic</em> in hash rate, not linear. A fleet spans eleven orders of magnitude between a 2009 laptop and a modern megacampus, so a linear reward would pay the opening years nothing and the closing years absurdities. In practice a laptop earns about 8 XP a day and a 324 PH/s campus about 51 — roughly a six-fold spread across that whole range, which keeps the bar meaningful in every era. The share count itself is modelled the honest way, as <code>hash × 86,400 ÷ 2³²</code> difficulty-one shares per day.</p><p>The <strong>best share</strong> figure beside the bar is the one number solo miners actually watch: the highest-difficulty share your fleet has ever found. It is drawn from a heavy-tailed distribution around your daily share count, so it climbs in rare jumps rather than smoothly, and beating your own record by a wide margin is announced. It is a personal record, not a block — finding it changes nothing about your payout.</p><p>Level <em>N</em> needs <code>60 × (N−1)²</code> cumulative XP, so early levels arrive in days and later ones take seasons. Levels grant skill points on a decelerating schedule — every level to 6, then every second level to 20, then every fourth — which works out at roughly 22 points across a long campaign, against the 80 needed to buy the entire tech tree. A full historical run played actively lands somewhere around level 55.</p><p>XP <strong>augments</strong> the Operator Score rather than replacing it, and the distinction matters: XP only ever goes up, so on its own it would reward sitting still for seventeen years. Peak level therefore contributes a capped 60 points of <em>mastery</em> (reached at level 50), taken out of the era-performance allocation, which now carries 740 rather than 800. The remaining 200 still come from milestones, holdings, reserves and resilience, and the Score keeps every one of its penalties for bridge loans and receivership. Operating well and operating long are scored as two different things.</p><h3 id="method-progression">Learning, skills and operating strategy</h3><p>One forum post, book or podcast occupies the single learning slot at a time; some finish with a knowledge check, and crossing a knowledge threshold — like major story events and mining milestones — awards a skill point. The first threshold is 5 knowledge, and every threshold after it is three further knowledge, so the Tech tree opens early in a run and then compounds steadily. Skills change real calculations rather than adding score directly: Compute skills touch hash and hardware cost, Energy skills touch power cost, Operations skills touch pool fees, uptime, relocation and connectivity risk, and Treasury skills touch loan and custody-transfer economics. Power contracts trade a cheaper spot-market rate for exposure to energy shocks; staff add recurring salary for a targeted benefit, and field technicians specifically are the input that keeps fleet wear and repair times down. Any role can be dismissed again from the Finance desk: salary stops immediately and one month's notice is added to that month's accrued bill, so hiring a crew for a single job and letting them go is not free. A technician already committed to a running repair cannot be dismissed until that job clears, and losing your last technician switches auto-repair back off and returns you to the bench.</p><h3 id="method-risk">Optional risk and civil-society actions</h3><p>Historical-era speculative bets risk a chosen slice of hot-wallet BTC with deterministic, loss-biased outcomes. Donations send a chosen portion of hot-wallet BTC permanently. Neither is required to finish the game.</p>`},
    {id:"method-sources",title:"Recorded history and sources",summary:"The bundled datasets, how values between anchors are derived, and where events come from.",lead:"This is the provenance chapter. Recorded values come from the bundled historical dataset. Derived values are calculated from recorded inputs, usually by interpolating between anchors. Modelled values are gameplay assumptions. Anything not described here as recorded is one of the other two.",body:`<h3 id="method-events">Historical events and sources</h3><p>Event cards mix protocol, mining, custody, policy, adoption and market-structure milestones. Each shows a modelled 30-day BTC price-path comparison as context only, not a causal claim; a small set of dated events changes gameplay directly — venue failures, regional shutdowns — and major events can award skill points.</p>${recordedMetricSnapshot()}`},
    {id:"method-sandbox",title:"Procedural sandbox",summary:"What continues after the recorded history ends, what stops, and which values become modelled.",lead:"Past the historical cutoff the simulation keeps running on projections. This chapter is the line between the two: what the sandbox refuses to invent, what it models deterministically, and what keeps happening because the protocol says so.",body:`<h3 id="method-sandbox-model">What the sandbox invents, and what it refuses to</h3><p>The bundled historical record ends on ${dateFmt(END)}. Continuing past that point starts the procedural sandbox: the same operation and the same rules, for up to 100 further simulated years — but every input is now a projection rather than a recorded value.</p><h4>What stops at the cutoff</h4><p>No new historical chapters and no new hardware releases exist after ${dateFmt(END)}, because nothing real exists to add. The story feed goes quiet and the hardware catalogue stops growing: the newest machine available on the last recorded day is the newest machine you will ever buy. Nothing the game shows you after the cutoff is recorded history.</p><h4>What continues as a model</h4><p>Price, network hash rate, network difficulty, transaction activity, transaction fees, chain size and block height all continue. Each is a deterministic function of the date alone — the same date always produces the same value, and the live gameplay random number generator is never consulted, so re-rendering a screen can never change a projected figure. Price follows a decaying growth trend anchored to its last recorded value, shaped by a halving cycle measured from the history you have just replayed: detrending each complete recorded epoch and averaging the log residual by phase gives a trough just after the halving, a peak about a third of the way through, a long drawdown and a recovery into the next one. Its amplitude starts below the historical figure, because the most recent epoch was already far flatter than the first, and decays as the asset matures. The wobble around it is sized from recorded volatility, which fell from roughly 139% annualised across 2011-13 to 46% across 2023-26, and continues that decay. Hash rate follows the same cycle with a lag and a third of the swing, because capacity is ordered after a rally and lands months later; difficulty follows hash rate; block height advances at a constant ten-minute interval. These are bounded projections built to keep operating decisions meaningful. They are not forecasts.</p><h4>What continues as protocol</h4><p>Bitcoin's issuance schedule is not a projection. The subsidy halves every 210,000 blocks and keeps doing so. What is projected is <em>when</em>: the sandbox assumes a constant ten-minute block interval, so each halving lands about 3 years and 11 months after the last. Real block intervals vary, so treat every projected halving date as modelled and the direction as certain.</p><p>The first projected halving falls in ${dateFmt(nextHalvingTime(END),true)} and takes the subsidy from ${fmtSubsidy(subsidyAt(END))} to ${fmtSubsidy(subsidyAt(nextHalvingTime(END)))} per block. Twenty-five projected halvings occur before the sandbox ends. Each one is recorded in your Ledger and announced as a <strong>Projected protocol halving</strong> — never as a historical chapter — and each is a reason to re-check your mining margin, because the same hash rate earns half the subsidy it did the day before.</p><h4>Whole satoshis</h4><p>Bitcoin has no unit smaller than a satoshi, and the subsidy is halved by integer division. ${fmtSubsidy(subsidyAt(END))} is ${Math.round(subsidyAt(END)*1e8).toLocaleString("en-US")} satoshis; every halving floors the result rather than keeping a fraction. From the tenth halving onward that flooring is visible — 4,882,812 satoshis rather than 4,882,812.5 — and this simulation floors it the same way, so no payout, forecast or displayed value ever contains a fraction of a satoshi. By the end of the sandbox the projected subsidy is ${fmtSubsidy(subsidyAt(SANDBOX_END))} per block, and transaction fees dominate mining revenue completely.</p><h4>The endpoint</h4><p>The sandbox is finite. It ends 100 years after the historical cutoff, on ${dateFmt(SANDBOX_END)}, and there is no further continuation to accept: the run closes with the same final recap as the historical ending.</p>`}
  ];
}
/* Provenance for the bundled dataset. It lived in bootstrap.js as an alpha-2.5 patch; it belongs with the chapter that explains where recorded values come from. */
function recordedMetricSnapshot(){
  return `<section class="strategy-method-guide"><h3>Recorded metric snapshot</h3><p>The historical engine is bundled locally and never changes during a run. It contains a daily observation for every series it can — market price, a 14-day hash rate mean, seven-day fee and transaction means and cumulative block height — plus one exact difficulty value per 2016-block retarget, through ${DATA_META.through||"the historical cutoff"}.</p><table><tr><th>Metric</th><th>Offline points</th><th>How the game uses it</th></tr><tr><td>BTC / USD</td><td>${fmtNum(PRICE.length)}</td><td>Daily market value and fiat revenue</td></tr><tr><td>Difficulty</td><td>${fmtNum(DIFFICULTY.length)}</td><td>One exact step per retarget · primary expected block-yield calculation</td></tr><tr><td>Network hash rate</td><td>${fmtNum(HASH.length)}</td><td>Smoothed context, charts and competitive floor</td></tr><tr><td>Fees / block</td><td>${fmtNum(FEES.length)}</td><td>Seven-day mean added to the subsidy</td></tr><tr><td>Transactions / day</td><td>${fmtNum(TX.length)}</td><td>Seven-day activity context and Lightning scaling</td></tr></table><p class="modal-note">Source: <a href="${DATA_META.sourceUrl||"https://community-api.coinmetrics.io/v4/timeseries/asset-metrics"}" target="_blank" rel="noopener">${DATA_META.source||"Coin Metrics Community Network Data"}</a>. Difficulty comes from <a href="${DATA_META.difficultySourceUrl||"https://mempool.space/api/v1/mining/difficulty-adjustments/all"}" target="_blank" rel="noopener">mempool.space's published difficulty adjustments</a>: one exact value per 2016-block retarget, held until the next one, because that is the only time the protocol changes it. Early competition scaling, hardware economics and operational outcomes remain explicitly modelled for gameplay.</p></section>`;
}
function methodTocHtml(chapters){
  return `<nav class="method-toc" aria-label="Method chapters"><h3>The manual in eight chapters</h3><button class="action small method-glossary-link" data-action="glossary">Look up a term in the glossary</button><ol>${chapters.map((chapter,index)=>`<li><button class="method-toc-link" data-action="method-chapter" data-id="${chapter.id}"><span class="method-toc-number">${index+1}</span><b>${chapter.title}</b><span>${chapter.summary}</span></button></li>`).join("")}</ol></nav>`;
}
function methodDetailIds(body,chapterId){let n=0;return body.replace(/<details class="method-detail">/g,()=>{const id=`${chapterId}-detail-${++n}`;return `<details class="method-detail" id="${id}" ${methodOpenChapters.has(id)?"open":""}>`})}
function methodChapterHtml(chapter,index){
  return `<details class="method-chapter" id="${chapter.id}" ${methodOpenChapters.has(chapter.id)?"open":""}><summary><span class="method-chapter-number">Chapter ${index+1}</span><b>${chapter.title}</b><span class="method-chapter-summary">${chapter.summary}</span></summary><div class="method-chapter-body"><p class="method-chapter-lead">${chapter.lead}</p>${methodDetailIds(chapter.body,chapter.id)}</div></details>`;
}
function method(){
  const chapters=methodChapters();
  return `<article class="card card-pad method"><div class="hero-kicker">Method &amp; game economics</div><h2>Operator manual: what the simulation actually does.</h2><p>Recorded values come from a bundled historical dataset. Derived values are calculated from those recordings. Everything else — hardware pricing, incidents, uptime, fee outcomes and every value after the historical cutoff — is a gameplay model built to expose operating trade-offs, not a forecast or investment advice.</p>${methodTocHtml(chapters)}${chapters.map(methodChapterHtml).join("")}</article>`;
}
function techV2(){
  const branches=["Compute","Energy","Operations","Treasury"];
  return `<div class="grid"><section class="card span-12"><div class="hero"><div><div class="hero-kicker">Operator specialisation</div><h1>Build capability, not instant multipliers.</h1><p>Later tiers need more points, the right historical era and an operation large enough to use them. Existing unlocked skills remain valid, but new unlocks follow the rebalanced gates.</p></div><div class="hero-stat"><strong>${state.points}</strong><span>unspent skill points</span></div></div></section><section class="span-12 tech-trees">${branches.map(branch=>{const skills=SKILLS.filter(s=>s.branch===branch),unlocked=skills.filter(s=>hasSkill(s.id)).length;return `<article class="tech-tree"><div class="tech-tree-head"><span>${branch} tree</span><span>${unlocked} / ${skills.length} unlocked</span></div><div class="tree-nodes">${skills.map((skill,index)=>{const done=hasSkill(skill.id),gate=done?"":skillGateReason(skill),enough=state.points>=skill.cost,ready=!gate,status=done?"Unlocked":gate||(!enough?`Need ${skill.cost} point${skill.cost===1?"":"s"}`:"Ready to unlock"),requirements=[skill.req?`follows ${SKILLS.find(x=>x.id===skill.req)?.name}`:"foundation",skill.date?dateFmt(at(skill.date),true):null,skill.minFacility?`tier ${skill.minFacility}+ facility`:null].filter(Boolean).join(" · ");return `<div class="tree-node ${done?"unlocked":ready?"ready":""}"><div class="skill-branch">Tier ${index+1}</div><h3>${skill.name}</h3><p>${skill.desc}</p><div class="tree-cost">${skill.cost} point${skill.cost===1?"":"s"} · ${requirements}</div><div class="tree-state">${status}</div><button class="action small ${done?"":"primary"}" data-action="skill" data-id="${skill.id}" ${done||!ready||!enough?"disabled":""}>${done?"Unlocked":"Unlock"}</button></div>`}).join("")}</div></article>`}).join("")}</section></div>`;
};
function changeLogHtml(){return `<details class="card" style="margin-top:18px"><summary style="cursor:pointer;font:600 12px var(--mono);padding:16px;color:var(--orange2)">Permanent change log · ${CHANGELOG.length} releases</summary><div class="card-pad">${CHANGELOG.map(entry=>`<section style="padding:4px 0 16px"><div class="hero-kicker">${entry.date}</div><h3>${entry.title}</h3><ul>${entry.items.map(item=>`<li>${item}</li>`).join("")}</ul></section>`).join("")}</div></details>`}
function enhanceMethod(){const guide=document.querySelector(".method");if(!guide||guide.dataset.appended)return;guide.dataset.appended="1";guide.insertAdjacentHTML("beforeend",balanceLabHtml()+changeLogHtml());}
